1	<!doctype html>
2	<html lang="he" dir="rtl">
3	<head>
4	<link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png">
5	<link rel="icon" type="image/png" sizes="256x256" href="/favicon-256.png">
6	<link rel="apple-touch-icon" href="/apple-touch-icon.png">
7	<meta charset="utf-8">
8	<meta name="viewport" content="width=device-width, initial-scale=1">
9	<title>NanoShellano · מסך פתיחה</title>
10	<!-- nc-og -->
11	<meta property="og:type" content="website">
12	<meta property="og:site_name" content="NanoShellano">
13	<meta property="og:locale" content="he_IL">
14	<meta property="og:url" content="https://nanoshellano.vercel.app/">
