25	<link rel="preconnect" href="https://fonts.googleapis.com">
26	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
27	<link href="https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;500;600;700;800&family=Baloo+2:wght@500;600;700;800&display=swap" rel="stylesheet">
28	<style>
29	:root{
30	  --paper:#000000; --panel:#0E0E0E; --panel-2:#141414;
31	  --ink:#FFFFFF; --ink-muted:#B0B0B0; --ink-dim:#6F6F6F;
32	  --teal:#56EDD6; --on-teal:#04211D;
33	  --line:#242424; --line-soft:#1C1C1C;
34	  --sans:'Heebo',system-ui,sans-serif; --round:'Baloo 2','Heebo',sans-serif;
35	}
36	*{box-sizing:border-box;margin:0;padding:0}
37	html,body{background:var(--paper);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
38	body{min-height:100vh;line-height:1.7}
39	
40	/* top bar - logo on the menu side, teal-pill language toggle opposite; mirrors with page dir (HE: logo right/toggle left; EN: mirrored) */
41	.topbar{display:flex;align-items:center;justify-content:space-between;padding:13px 30px;border-bottom:1px solid rgba(255,255,255,.05);position:sticky;top:0;background:rgba(0,0,0,.72);backdrop-filter:blur(10px);z-index:20}
42	.tb-logo{height:46px;width:auto;display:block}
43	.lang-toggle{display:flex;border:1px solid var(--line);border-radius:100px;overflow:hidden}
44	.lang-toggle button{background:transparent;border:none;color:var(--ink-dim);font-family:var(--round);font-weight:600;font-size:13px;letter-spacing:.03em;padding:6px 16px;cursor:pointer;transition:background .15s,color .15s}
45	.lang-toggle button.on{background:var(--teal);color:#04211D}
46	.lang-toggle button:not(.on):hover{color:var(--ink)}
47	
48	.wrap{max-width:1060px;margin:0 auto;padding:0 24px 88px}
49	
50	/* hero - first-version constructed lockup: big mascot + Nano/Shellano wordmark + glow */
51	.hero{text-align:center;padding:42px 6px 6px;position:relative}
52	.glow{position:absolute;top:0;left:50%;transform:translateX(-50%);width:540px;height:420px;background:radial-gradient(circle, rgba(86,237,214,.18) 0%, rgba(86,237,214,.055) 42%, transparent 72%);pointer-events:none;z-index:0}
53	.hero>*:not(.glow){position:relative;z-index:1}
54	.hero-mascot{width:min(216px,48%);height:auto;display:block;margin:0 auto 14px;filter:drop-shadow(0 14px 38px rgba(86,237,214,.22))}
55	.wordmark{font-family:var(--round);font-weight:800;font-size:clamp(38px,7vw,62px);line-height:1;letter-spacing:-.01em;margin-bottom:30px}
56	.wordmark .wm-n{color:#FFFFFF}
57	.wordmark .wm-s{color:var(--teal)}
58	.hero-from{font-size:13.5px;color:var(--ink-dim);letter-spacing:.02em;margin-bottom:30px}
59	.h1{font-family:var(--round);font-weight:700;font-size:clamp(29px,4.8vw,46px);line-height:1.18;margin-bottom:18px;max-width:760px;margin-inline:auto}
60	.h1 .l1{color:#FFFFFF}
61	.h1 .l2{color:var(--teal)}
62	.lead{font-size:clamp(16px,1.8vw,19.5px);color:var(--ink-muted);font-weight:400;line-height:1.65;max-width:600px;margin:0 auto}
63	.lead b{color:#FFFFFF;font-weight:600}
64	.hero-cta{margin-top:30px}
65	.hero-cta a{display:inline-flex;align-items:center;gap:10px;background:var(--teal);color:var(--on-teal);font-family:var(--round);font-weight:700;font-size:17px;padding:15px 36px;border-radius:100px;text-decoration:none;transition:.2s;box-shadow:0 10px 34px rgba(86,237,214,.18)}
66	.hero-cta a:hover{filter:brightness(1.08);transform:translateY(-1px)}
67	.trust{margin-top:16px;font-size:13.5px;color:var(--ink-dim);letter-spacing:.02em}
68	
69	/* personal manifesto - the heart of the project, in Elia's own voice. WIDE power-paragraph: flows across the page, sentences wrap naturally, low scroll. No box. */
70	.manifesto{max-width:940px;margin:46px auto 0;text-align:center}
71	.manifesto p{font-size:clamp(17px,1.7vw,20px);line-height:1.85;color:var(--ink-muted);margin-bottom:17px}
72	.manifesto p:last-child{margin-bottom:0}
73	.manifesto p.m-accent{color:#FFFFFF;font-family:var(--round);font-weight:600;font-size:clamp(18px,1.85vw,21px);line-height:1.6}
74	.manifesto p.m-close{color:var(--teal);font-family:var(--round);font-weight:700;font-size:clamp(19px,2.05vw,23px);line-height:1.5;margin-top:8px}
75	
76	/* single short beat - the agent is a digital worker */
77	.beat{max-width:660px;margin:0 auto;padding-top:52px;text-align:center}
78	.beat h2{font-family:var(--round);font-weight:700;font-size:clamp(22px,2.8vw,30px);color:#FFFFFF;line-height:1.28;margin-bottom:16px}
79	.beat p{font-size:clamp(16px,1.55vw,18px);line-height:1.8;color:var(--ink-muted)}
80	
81	/* persona picker */
82	.pick{margin-top:60px}
83	.pick-q{text-align:center;font-family:var(--round);font-weight:700;font-size:clamp(25px,3vw,34px);margin-bottom:12px;color:#FFFFFF}
84	.pick-sub{text-align:center;font-size:clamp(15px,1.5vw,17px);color:var(--ink-muted);line-height:1.65;max-width:600px;margin:0 auto 34px}
85	.roles{display:grid;grid-template-columns:repeat(auto-fill,minmax(248px,1fr));gap:13px}
86	.role{display:flex;align-items:center;gap:14px;padding:17px 19px;border:1px solid var(--line);background:var(--panel);border-radius:15px;cursor:pointer;transition:border-color .2s, background .2s, transform .12s;text-align:start;position:relative;overflow:hidden}
87	.role::before{content:'';position:absolute;inset-inline-start:0;top:0;bottom:0;width:3px;background:var(--teal);transform:scaleY(0);transform-origin:center;transition:transform .2s}
88	.role:hover{border-color:rgba(86,237,214,.5);background:var(--panel-2);transform:translateY(-2px)}
89	.role:hover::before{transform:scaleY(1)}
90	.role .body{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}
91	.role .ttl{font-size:16.5px;font-weight:700;color:#FFFFFF;line-height:1.2}
92	.role .desc{font-size:12.5px;color:var(--ink-muted);line-height:1.45}
93	.role .arr{flex:0 0 auto;color:var(--ink-dim);font-size:19px;line-height:1;transition:color .2s, transform .2s}
94	.role:hover .arr{color:var(--teal);transform:translateX(-3px)}
95	.role.soon{opacity:.5;cursor:default}
96	.role.soon:hover{border-color:var(--line);background:var(--panel);transform:none}
97	.role.soon:hover::before{transform:scaleY(0)}
98	.role.soon .arr{display:none}
99	.role .soon-tag{flex:0 0 auto;font-size:11px;color:var(--ink-dim);border:1px solid var(--line);border-radius:100px;padding:3px 10px;white-space:nowrap}
100	.pick-fallback{text-align:center;margin-top:26px;font-size:14px}
101	.pick-fallback a{color:var(--ink-dim);text-decoration:none;border-bottom:1px solid var(--line);padding-bottom:2px;transition:.2s}
102	.pick-fallback a:hover{color:var(--teal);border-color:var(--teal)}
103	
104	/* one quiet NanoClaw line, after the picker - must not dominate */
105	.nano{max-width:640px;margin:56px auto 0;border:1px solid var(--line);background:var(--panel);border-radius:18px;padding:24px 30px;text-align:center}
106	.nano p{font-size:15px;line-height:1.75;color:var(--ink-muted)}
107	.nano b{color:#FFFFFF;font-weight:600}
108	
109	/* bottom strip - living guide + leave details */
110	.strip{margin-top:56px;border:1px solid var(--line);background:var(--panel);border-radius:22px;padding:36px 30px;text-align:center}
111	.strip .s-ttl{font-family:var(--round);font-weight:700;font-size:clamp(20px,2.1vw,25px);color:#FFFFFF;margin-bottom:12px}
112	.strip .s-sub{font-size:15.5px;color:var(--ink-muted);line-height:1.7;max-width:580px;margin:0 auto}
113	
114	@media(max-width:560px){
115	  .topbar{padding:14px 20px}
116	  .wrap{padding:0 20px 72px}
117	  .hero{padding:32px 4px 6px}
118	  .hero-mascot{width:min(180px,46%)}
119	  .hero-from{margin-bottom:24px}
120	  .beat{padding-top:46px}
121	  .manifesto{margin-top:36px;max-width:none}
122	  .manifesto p{font-size:16px;line-height:1.62;margin-bottom:12px}
123	  .manifesto p.m-accent{font-size:17px;line-height:1.45}
124	  .manifesto p.m-close{font-size:18px;line-height:1.4;margin-top:6px}
125	  .pick{margin-top:48px}
126	  .roles{grid-template-columns:1fr;gap:11px}
127	  .nano{margin-top:48px;padding:22px 22px}
128	  .strip{padding:30px 20px}
129	}
130	</style>
131	</head>
132	<body>
133	
134	<div class="topbar">
135	  <img class="tb-logo" src="shots/nanoshellano-lockup-trim.png" alt="NanoShellano">
136	  <div class="lang-toggle">
137	    <button data-l="en" onclick="setLang('en')">EN</button>
138	    <button data-l="he" class="on" onclick="setLang('he')">HE</button>
139	  </div>
140	</div>
141	
142	<div class="wrap">
143	
144	  <!-- HERO - constructed lockup (first version): mascot + Nano/Shellano wordmark + glow -->
145	  <section class="hero">
146	    <div class="glow"></div>
147	    <img class="hero-mascot" src="shots/nanoshellanoo.png" alt="NanoShellano">
148	    <div class="wordmark"><span class="wm-n">Nano</span><span class="wm-s">Shellano</span></div>
149	    <h1 class="h1"><span class="l1" data-he="הגשר שלך לעולם של " data-en="Your bridge to the world of ">הגשר שלך לעולם של </span><span class="l2" data-he="סוכני AI." data-en="AI agents.">סוכני AI.</span></h1>
150	    <p class="lead" data-he="לא צריך לדעת קוד. לא צריך להיות טכנולוגיים. צריך להבין איך להקים סוכן <b>שעובד בשבילכם</b>, ואיך לנהל אותו נכון." data-en="You don't need to code. You don't need to be technical. You need to understand how to set up an agent <b>that works for you</b>, and how to manage it well.">לא צריך לדעת קוד. לא צריך להיות טכנולוגיים. צריך להבין איך להקים סוכן <b>שעובד בשבילכם</b>, ואיך לנהל אותו נכון.</p>
151	    <div class="hero-cta"><a href="#pick" data-he="בואו נתחיל להקים" data-en="Let's start setting up">בואו נתחיל להקים</a></div>
152	  </section>
153	
154	  <!-- MANIFESTO - Elia's personal text, verbatim words; wide flowing power-paragraphs (no forced line breaks); bridges into the picker -->
155	  <section class="manifesto">
156	    <p data-he="כל הזמן אומרים לנו שה-AI הולך לשנות את העבודה. ואני חושב על זה הרבה לאחרונה. אבל אולי השינוי האמיתי הוא לא ש-AI עושה את העבודה במקומנו. אולי הוא שלכל אחד מאיתנו יהיה סוכן משלו." data-en="We keep being told that AI is going to change the way we work. And lately, I've been thinking about it a lot. But maybe the real change isn't AI doing the work for us. Maybe it's that each of us will have an agent of our own.">כל הזמן אומרים לנו שה-AI הולך לשנות את העבודה. ואני חושב על זה הרבה לאחרונה. אבל אולי השינוי האמיתי הוא לא ש-AI עושה את העבודה במקומנו. אולי הוא שלכל אחד מאיתנו יהיה סוכן משלו.</p>
157	    <p data-he="לא כלי שצריך ללמוד. לא תוכנה שצריך להפעיל. משהו שפשוט מדברים איתו, כמו שמדברים עם בנאדם. ופתאום זה כבר לא שייך רק למתכנתים." data-en="Not a tool you have to learn. Not software you have to operate. Something you simply talk to, the way you'd talk to a person. And suddenly, it no longer belongs only to programmers.">לא כלי שצריך ללמוד. לא תוכנה שצריך להפעיל. משהו שפשוט מדברים איתו, כמו שמדברים עם בנאדם. ופתאום זה כבר לא שייך רק למתכנתים.</p>
158	    <p data-he="זה גורם לי לחשוב שאולי הטכנולוגיה הזו לא אמורה להיות מעלינו. היא אמורה לעבוד בשבילנו. ואם זה נכון, אז היא צריכה להיות פתוחה לכל אחד. גם למי שמעולם לא כתב שורת קוד." data-en="It makes me think that maybe this technology isn't meant to stand above us. It's meant to work for us. And if that's true, then it has to be open to everyone. Even to those who have never written a single line of code.">זה גורם לי לחשוב שאולי הטכנולוגיה הזו לא אמורה להיות מעלינו. היא אמורה לעבוד בשבילנו. ואם זה נכון, אז היא צריכה להיות פתוחה לכל אחד. גם למי שמעולם לא כתב שורת קוד.</p>
159	    <p class="m-accent" data-he="לכן בניתי את המדריך הזה. ונתתי אותו חינם." data-en="So I built this guide. And I made it free.">לכן בניתי את המדריך הזה. ונתתי אותו חינם.</p>
160	    <p data-he="הוא לוקח אותך צעד צעד, בשפה שלך, מאפס ועד סוכן אישי שמדבר איתך. בלי רקע טכני, בלי שצריך להבין הכל לבד." data-en="It takes you step by step, in your own language, from zero to a personal agent that talks with you. No technical background, no need to figure it all out alone.">הוא לוקח אותך צעד צעד, בשפה שלך, מאפס ועד סוכן אישי שמדבר איתך. בלי רקע טכני, בלי שצריך להבין הכל לבד.</p>
161	    <p class="m-close" data-he="כי אולי העולם החדש הזה לא נמדד במי שיודע להשתמש בטכנולוגיה, אלא במי שמרשה לעצמו לנסות." data-en="Because maybe this new world isn't measured by who knows how to use technology, but by who lets themselves try.">כי אולי העולם החדש הזה לא נמדד במי שיודע להשתמש בטכנולוגיה, אלא במי שמרשה לעצמו לנסות.</p>
162	  </section>
163	
164	  <!-- PICKER -->
165	  <section class="pick" id="pick">
166	    <div class="pick-q" data-he="בניתי לכם סוכן מותאם אישית לכל תפקיד." data-en="I built you a personalized agent for every role.">בניתי לכם סוכן מותאם אישית לכל תפקיד.</div>
167	    <div class="pick-sub" data-he="בחרו את התפקיד שלכם, ותדעו בדיוק מה הסוכן יכול לעשות בשבילכם." data-en="Choose your role, and see exactly what your agent can do for you.">בחרו את התפקיד שלכם, ותדעו בדיוק מה הסוכן יכול לעשות בשבילכם.</div>
168	    <div class="roles">
169	
170	      <button class="role" data-slug="hr" onclick="go('hr')"><span class="body"><span class="ttl" data-he="HR" data-en="Human Resources">HR</span><span class="desc" data-he="גיוס, קליטה, עובדים ותפעול HR" data-en="Hiring, onboarding, people, HR ops">גיוס, קליטה, עובדים ותפעול HR</span></span><span class="arr">←</span></button>
171	
172	      <button class="role" data-slug="learning-development" onclick="go('learning-development')"><span class="body"><span class="ttl" data-he="למידה ופיתוח ארגוני" data-en="Learning &amp; Development">למידה ופיתוח ארגוני</span><span class="desc" data-he="אפיונים, תוכן, LMS, ספקים ומדידה" data-en="Needs analysis, content, LMS, vendors, measurement">אפיונים, תוכן, LMS, ספקים ומדידה</span></span><span class="arr">←</span></button>
173	
174	      <button class="role" data-slug="sales" onclick="go('sales')"><span class="body"><span class="ttl" data-he="מכירות" data-en="Sales">מכירות</span><span class="desc" data-he="לידים, פייפליין, פגישות ופולואו-אפים" data-en="Leads, pipeline, meetings, follow-ups">לידים, פייפליין, פגישות ופולואו-אפים</span></span><span class="arr">←</span></button>
175	
176	      <button class="role" data-slug="marketing" onclick="go('marketing')"><span class="body"><span class="ttl" data-he="שיווק" data-en="Marketing">שיווק</span><span class="desc" data-he="מחקר, תוכן, קמפיינים ואופטימיזציה" data-en="Research, content, campaigns, optimization">מחקר, תוכן, קמפיינים ואופטימיזציה</span></span><span class="arr">←</span></button>
177	
178	      <button class="role" data-slug="executive" onclick="go('executive')"><span class="body"><span class="ttl" data-he="הנהלה" data-en="Executive">הנהלה</span><span class="desc" data-he="ביצוע, סנכרון, החלטות ותמונת מצב" data-en="Execution, alignment, decisions, overview">ביצוע, סנכרון, החלטות ותמונת מצב</span></span><span class="arr">←</span></button>
179	
180	      <button class="role" data-slug="business-owners" onclick="go('business-owners')"><span class="body"><span class="ttl" data-he="בעלי עסקים" data-en="Business Owners">בעלי עסקים</span><span class="desc" data-he="לקוחות, משימות, שיווק ותפעול" data-en="Clients, tasks, marketing, operations">לקוחות, משימות, שיווק ותפעול</span></span><span class="arr">←</span></button>
181	
182	      <button class="role" data-slug="job-seekers" onclick="go('job-seekers')"><span class="body"><span class="ttl" data-he="מחפשי עבודה" data-en="Job Seekers">מחפשי עבודה</span><span class="desc" data-he="משרות, קורות חיים, נטוורקינג וראיונות" data-en="Roles, resume, networking, interviews">משרות, קורות חיים, נטוורקינג וראיונות</span></span><span class="arr">←</span></button>
183	
184	      <button class="role" data-slug="finance" onclick="go('finance')"><span class="body"><span class="ttl" data-he="כספים" data-en="Finance">כספים</span><span class="desc" data-he="דוחות, בקרה, תחזיות ותזרים" data-en="Reports, control, forecasts, cash flow">דוחות, בקרה, תחזיות ותזרים</span></span><span class="arr">←</span></button>
185	
