// Builds the branded bilingual HTML from pilot-terms-privacy-draft.md.
// Content is parsed from the md so the two files can never drift.
const fs = require('fs');
const md = fs.readFileSync(__dirname + '/pilot-terms-privacy-draft.md', 'utf8');
const lines = md.split('\n');

// split into segments by PART markers
const idxA = lines.findIndex(l => l.startsWith('# PART A'));
const idxB = lines.findIndex(l => l.startsWith('# PART B'));
const idxC = lines.findIndex(l => l.startsWith('# PART C'));
const segHeader = lines.slice(0, idxA);
const segEn = lines.slice(idxA + 1, idxB);
const segHe = lines.slice(idxB + 1, idxC);
const segNotes = lines.slice(idxC + 1);

const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = s => esc(s)
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/`([^`]+)`/g, '<code>$1</code>');

function render(seg) {
  const out = [];
  let ul = false;
  const closeUl = () => { if (ul) { out.push('</ul>'); ul = false; } };
  for (const raw of seg) {
    const l = raw.trimEnd();
    if (!l.trim()) { closeUl(); continue; }
    if (l.trim() === '***') { closeUl(); out.push('<hr>'); continue; }
    let m;
    if ((m = l.match(/^### (.*)/))) { closeUl(); out.push('<h4>' + inline(m[1]) + '</h4>'); continue; }
    if ((m = l.match(/^## (.*)/)))  { closeUl(); out.push('<h3>' + inline(m[1]) + '</h3>'); continue; }
    if ((m = l.match(/^# (.*)/)))   { closeUl(); out.push('<h2>' + inline(m[1]) + '</h2>'); continue; }
    if ((m = l.match(/^\* (.*)/))) {
      if (!ul) { out.push('<ul>'); ul = true; }
      out.push('<li>' + inline(m[1]) + '</li>'); continue;
    }
    closeUl(); out.push('<p>' + inline(l) + '</p>');
  }
  closeUl();
  return out.join('\n');
}

