/* ---------------- apply ---------------- */
const errors = [];
for (const [o, n] of P) {
  const count = html.split(o).length - 1;
  if (count !== 1) { errors.push(`count=${count} :: ${o.slice(0, 70)}`); continue; }
  html = html.replace(o, n);
}
if (errors.length) {
  console.error('ABORT, bad matches:'); errors.forEach(e => console.error(' ', e));
  process.exit(1);
}
fs.writeFileSync(OUT, html);
console.log('OK,', P.length, 'replacements applied.', (html.length / 1024).toFixed(1) + 'KB');

