585	function paintChrome(){
586	  const t=T[L];
587	  document.documentElement.lang=L;
588	  document.documentElement.dir = L==='he'?'rtl':'ltr';
589	  document.getElementById('back').textContent = L==='he'?'→':'←';
590	  document.getElementById('lang').textContent = L==='he'?'EN':'עב';
591	  let p='';
592	  for(let k=0;k<N;k++) p+=`<div class="seg ${k<i?'done':''} ${k===i?'cur':''}"><i></i></div>`;
593	  document.getElementById('prog').innerHTML=p;
594	  document.getElementById('stepn').textContent=`${i+1}/${N}`;
595	  document.getElementById('back').disabled = i===0 || submitting;
596	  document.getElementById('foot').innerHTML=footHTML(t);
597	}
