599	function init(){
600	  const stage=document.getElementById('stage');
601	  const div=document.createElement('div');
602	  div.className='screen';
603	  div.innerHTML=screenHTML(T[L]);
604	  stage.appendChild(div);
605	  paintChrome();
606	}
607	function repaint(){
608	  const stage=document.getElementById('stage');
609	  stage.innerHTML='';
610	  const div=document.createElement('div');
611	  div.className='screen';
612	  div.innerHTML=screenHTML(T[L]);
613	  stage.appendChild(div);
614	  paintChrome();
615	}
616	function transition(dir){
617	  if(animating) return;
618	  animating=true;
619	  const stage=document.getElementById('stage');
620	  const old=stage.querySelector('.screen');
621	  const nw=document.createElement('div');
622	  nw.className='screen '+(dir>0?'in-fwd':'in-back');
623	  nw.innerHTML=screenHTML(T[L]);
624	  if(old){ old.classList.remove('in-fwd','in-back'); old.classList.add(dir>0?'out-fwd':'out-back'); }
625	  stage.appendChild(nw);
626	  paintChrome();
627	  setTimeout(()=>{ if(old&&old.parentNode) old.parentNode.removeChild(old); animating=false; },380);
628	}
629	function go(d){
630	  const ni=i+d;
631	  if(ni<0||ni>=N||animating||submitting) return;
632	  i=ni; transition(d);
633	}
