/* per-domain defaults: shellano.com opens in English + black icon; click2agent stays Hebrew */
const IS_SHELLANO = /(^|\.)shellano\.com$/i.test(location.hostname);
if (IS_SHELLANO){ document.querySelectorAll('link[rel*="icon"]').forEach(l=>{ l.href='/shellano_app_icon_512.png'; }); }
let lang = IS_SHELLANO ? 'en' : 'he';
function T(){ return S[lang]; }
function SC(){ return SCEN[lang]; }

function applyLang(){
  document.documentElement.lang = lang;
  document.documentElement.dir = lang === 'he' ? 'rtl' : 'ltr';
  document.title = T().docTitle;
  document.querySelectorAll('[data-i18n]').forEach(el=>{ el.textContent = T()[el.dataset.i18n]; });
  document.querySelectorAll('[data-i18n-html]').forEach(el=>{ el.innerHTML = T()[el.dataset.i18nHtml]; });
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{ el.placeholder = T()[el.dataset.i18nPh]; });
  // backBtn removed from header
  document.getElementById('tgName').textContent = T().tgName;
    document.querySelectorAll('#langToggle button').forEach(b=>b.classList.toggle('on', b.dataset.lang===lang));
  render();
}

document.querySelectorAll('#langToggle button').forEach(b=>{
  b.onclick = ()=>{
    if (b.dataset.lang === lang) return;
    lang = b.dataset.lang;
    applyLang();
    restartDemo();
  };
});

/* ================= navigation ================= */
const slides = Array.from(document.querySelectorAll('.slide'));
const N = slides.length;
let current = 0;
let userName = '';

const backBtn = null; // removed from header
const ctaBtn  = document.getElementById('ctaBtn');
const swipeHint = document.getElementById('swipeHint');
const ctaFoot = document.getElementById('ctaFoot');
const dotsEl  = document.getElementById('dots');
const soulLine = document.getElementById('soulLine');
const SOUL_KEYS = ['trust','manifesto','soul','pilSoul','formSoul'];
let soulShown = null;

for (let i = 0; i < N; i++) {
  const b = document.createElement('button');
  b.setAttribute('aria-label', 'screen ' + (i + 1));
  b.onclick = () => goTo(i);
  dotsEl.appendChild(b);
}
const dots = Array.from(dotsEl.children);

function render(){
  slides.forEach((s,i)=>{
    s.classList.toggle('active', i===current);
    s.classList.toggle('before', i>current);
  });
  dots.forEach((d,i)=>{ d.classList.toggle('on', i===current); d.setAttribute('aria-current', i===current ? 'true' : 'false'); });
  if (backBtn) backBtn.disabled = current===0;
  /* arrows appear from screen 2 onward (hidden on the hero) */
  if (arrBack){ arrBack.disabled = current===0; arrBack.classList.toggle('hidden', current===0); }
  if (arrFwd) { arrFwd.disabled  = current===N-1; arrFwd.classList.toggle('hidden', current===0 || current===N-1); }
  const c = T().cta[current];
  ctaBtn.textContent = c.label;
  swipeHint.style.display = c.hint ? 'flex' : 'none';
  ctaFoot.style.display = c.foot ? 'block' : 'none';
  ctaFoot.textContent = c.foot || '';
  const soulHtml = T()[SOUL_KEYS[current]] || '';
  if (soulHtml !== soulShown){
    soulShown = soulHtml;
    soulLine.style.opacity = '0';
    setTimeout(()=>{ if (soulShown === soulHtml){ soulLine.innerHTML = soulHtml; soulLine.style.opacity = '1'; } }, 180);
  }
  if (current===1) demoEnter();
  if (current===2){ revealEnter(2, true); readingCycle(2); }
  if (current===3) revealEnter(3);
  if (current===4) revealEnter(4);
  if (window.__trk) window.__trk.step(current);
}

function goTo(i){
  if (i<0 || i>=N || i===current) return;
  current = i;
  render();
}

// backBtn removed

const arrBack = document.getElementById('arrBack');
const arrFwd  = document.getElementById('arrFwd');
if (arrBack) arrBack.onclick = ()=>goTo(current-1);
if (arrFwd)  arrFwd.onclick  = ()=>goTo(current+1);
ctaBtn.onclick = ()=>{
  const a = T().cta[current].action;
