let touchX = null, touchY = null;
const stage = document.getElementById('stage');
stage.addEventListener('touchstart', e=>{ touchX=e.touches[0].clientX; touchY=e.touches[0].clientY; }, {passive:true});
stage.addEventListener('touchend', e=>{
  if (touchX===null) return;
  const dx = e.changedTouches[0].clientX - touchX;
  const dy = e.changedTouches[0].clientY - touchY;
  if (Math.abs(dx)>48 && Math.abs(dx)>Math.abs(dy)*1.4){
    if (dx<0) goTo(current+1); else goTo(current-1); /* swipe-left = forward */
  }
  touchX = null;
}, {passive:true});

/* ===== keep the phone hardware back button INSIDE the app =====
   Back goes to the previous slide instead of leaving the page,
   and never exits the app even on the first slide. */
history.replaceState({ app: true }, '');
history.pushState({ app: true }, '');
window.addEventListener('popstate', ()=>{
  if (current > 0) goTo(current - 1);
  /* always re-arm a buffer entry so a further back press stays in the app */
  history.pushState({ app: true }, '');
});

/* ============ reading highlight: glides card to card at reading pace ============ */
let readGen = 0;
function readingCycle(idx){
  const gen = ++readGen;
  const cards = Array.from(slides[idx].querySelectorAll('.card'));
  if (!cards.length) return;
  let i = 0;
  const tick = ()=>{
    if (gen !== readGen || current !== idx){ cards.forEach(c=>c.classList.remove('reading')); return; }
    cards.forEach(c=>c.classList.remove('reading'));
    cards[i].classList.add('reading');
    i = (i + 1) % cards.length;
    setTimeout(tick, 2000);
  };
  tick();
}

/* ================= staggered reveal (signup) ================= */
const revealedSlides = new Set();
function revealEnter(idx, instant){
  if (revealedSlides.has(idx)) return;
  revealedSlides.add(idx);
  const items = Array.from(slides[idx].querySelectorAll('.reveal-item'));
  items.forEach((el,i)=>{
    /* instant: whole list appears together on open; then the focus marker
       is the only element that steps one after another */
    setTimeout(()=>el.classList.add('in'), instant ? 120 : 260 + i*430);
  });
}

/* ================= signup ================= */
const VALIDATORS = {
  fFirst: v => v.trim().length >= 2
};

function validateField(wrapId){
  const wrap = document.getElementById(wrapId);
  const input = wrap.querySelector('input');
  const valid = VALIDATORS[wrapId](input.value);
  wrap.classList.toggle('invalid', !valid);
  return valid;
}

/* errors appear only after the user touches a field (blur) or tries to submit */
Object.keys(VALIDATORS).forEach(wrapId=>{
  const wrap = document.getElementById(wrapId);
  const input = wrap.querySelector('input');
  input.addEventListener('blur', ()=>{ if (input.value.trim() !== '') validateField(wrapId); });
  input.addEventListener('input', ()=>{ if (wrap.classList.contains('invalid')) validateField(wrapId); });
});
document.getElementById('inTgConsent').addEventListener('change', e=>{
  if (e.target.checked) document.getElementById('tgConsentWrap').classList.remove('invalid');
});
document.getElementById('inConsent').addEventListener('change', e=>{
  if (e.target.checked) document.getElementById('consentWrap').classList.remove('invalid');
});

/* source attribution: explicit ?src= tag wins; else auto-detect the domain.
   any new campaign link (?src=linkedin, ?src=facebook, ...) flows straight
   through to the dashboard with no code change. */
function computeSrc(){
  const p = new URLSearchParams(location.search).get('src');
  if (p) return p.trim().slice(0,64);
  const h = (location.hostname||'').toLowerCase();
  if (h.includes('click2agent') || h.includes('c2a')) return 'click2agent';
  if (h.includes('shellano')) return 'shellano';
  return '';
}

function submitForm(){
  let ok = true;
  Object.keys(VALIDATORS).forEach(wrapId=>{ if (!validateField(wrapId)) ok = false; });
  const tgConsent = document.getElementById('inTgConsent');
  document.getElementById('tgConsentWrap').classList.toggle('invalid', !tgConsent.checked);
  if (!tgConsent.checked) ok = false;
  const consent = document.getElementById('inConsent');
  document.getElementById('consentWrap').classList.toggle('invalid', !consent.checked);
  if (!consent.checked) ok = false;
  if (!ok){
    const firstInvalid = document.querySelector('.field.invalid input');
    if (firstInvalid) firstInvalid.focus();
    return;
  }
  userName = document.getElementById('inFirst').value.trim();
  ctaBtn.disabled = true;
  ctaBtn.textContent = T().submitting;
  const payload = {
    name: userName,
    lang: lang,
    src: computeSrc()
  };
  if (window.__trk) window.__trk.ev('register_submit', true);
  const FALLBACK = 'https://telegram.me/joni_agent_bot';
  // same-tab redirect (mobile Safari blocks window.open outside a direct tap)
  fetch('https://nanohubdemo.vercel.app/api/register', {
    method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload)
  })
  .then(r=>r.json())
  .then(d=>{ window.location.href = (d && d.deepLink) ? d.deepLink : FALLBACK; })
  .catch(()=>{ window.location.href = FALLBACK; });
}

/* ================= telegram demo: auto simulation, watch-it-happen ================= */
