/* ================= app journey tracker ================= *
 * Lightweight, forward-only. Sends one 'visit' on load and one 'session' on
 * exit (dwell, deepest screen, events) to the board's ingest endpoint.
 * Monitors the whole interface, not only people who leave details. */
(function(){
  var TA = 'https://provision.shellano.com/track';
  var t0 = Date.now();
  var vid = '';
  try { vid = localStorage.getItem('nc_app_vid') || ''; if(!vid){ vid = 'a'+Date.now().toString(36)+Math.random().toString(36).slice(2,8); localStorage.setItem('nc_app_vid', vid); } }
  catch(e){ vid = 'a'+Date.now().toString(36)+Math.random().toString(36).slice(2,8); }
  var src = (typeof computeSrc==='function') ? computeSrc() : '';
  var maxStep = 0, sent = false, submitted = false;
  var events = [];
  function push(name){ if(events.length<90) events.push({e:name, t:Date.now()-t0}); }
  function post(body){
    try{
      var s = JSON.stringify(body);
      if(navigator.sendBeacon){ navigator.sendBeacon(TA, new Blob([s], {type:'text/plain'})); }
      else { fetch(TA, {method:'POST', headers:{'Content-Type':'text/plain'}, body:s, keepalive:true}); }
    }catch(e){}
  }
  var TRK = {
    step: function(i){ if(i>maxStep) maxStep=i; push('screen_'+i); if(i>=4) push('reached_form'); },
    ev:   function(name, isSubmit){ push(name); if(isSubmit) submitted=true; },
  };
  window.__trk = TRK;
  // entry
  post({type:'visit', vid:vid, page:'app-landing', src:src, lang:(typeof lang!=='undefined'?lang:''), referrer:document.referrer||'', ua:navigator.userAgent, ts:new Date().toISOString()});
  push('screen_0');
  function flush(){
    if(sent) return; sent=true;
    post({type:'session', vid:vid, page:'app-landing', src:src, lang:(typeof lang!=='undefined'?lang:''),
      dwell_ms:Date.now()-t0, max_step:maxStep, submitted:submitted, events:events,
      ua:navigator.userAgent, ts:new Date().toISOString()});
  }
  window.addEventListener('pagehide', flush);
  document.addEventListener('visibilitychange', function(){ if(document.visibilityState==='hidden') flush(); });
})();
</script>
</body>
</html>

