521	function transition(dir){
522	  if(animating) return;
523	  animating=true;
524	  const stage=document.getElementById('stage');
525	  const old=stage.querySelector('.screen');
526	  const nw=document.createElement('div');
527	  nw.className='screen '+(dir>0?'in-fwd':'in-back');
528	  nw.innerHTML=screenHTML(T[L]);
529	  if(old){ old.classList.remove('in-fwd','in-back'); old.classList.add(dir>0?'out-fwd':'out-back'); }
530	  stage.appendChild(nw);
531	  paintChrome();
532	  setTimeout(()=>{ if(old&&old.parentNode) old.parentNode.removeChild(old); animating=false; },380);
533	}
534	function go(d){
535	  const ni=i+d;
536	  if(ni<0||ni>=N||animating||submitting) return;
537	  i=ni; howOpen=false; transition(d);
538	}
539	
540	/* ---- registration submit: the real backend call ---- */
541	async function submitReg(){
542	  if(!validReg()||submitting||animating) return;
543	  submitting=true; paintChrome();
544	  const payload={ name:reg.name.trim(), phone:reg.phone.trim(), email:reg.email.trim(), gender:reg.gender, lang:L, src:SRC };
545	  try{
546	    const r=await fetch('/api/register',{
547	      method:'POST',
548	      headers:{'Content-Type':'application/json'},
549	      body:JSON.stringify(payload)
550	    });
551	    const data=await r.json().catch(()=>null);
552	    deepLink=(data&&data.deepLink)?data.deepLink:BOT_FALLBACK;
553	  }catch(e){
554	    deepLink=BOT_FALLBACK;
555	  }
556	  submitting=false;
557	  i=3; howOpen=false; transition(1);
558	}
559	
560	/* ---- handoff: real Telegram deep link ---- */
561	function telegramOpen(){
562	  const t=T[L], sw=document.getElementById('switch');
563	  const url=deepLink||BOT_FALLBACK;
564	  sw.innerHTML=`<div class="ho-ico">✈️</div><h2>${t.sw_title}</h2><p>${t.sw_sub}</p>`;
565	  sw.classList.add('on');
566	  window.open(url,'_blank','noopener');
567	  setTimeout(()=>{ sw.classList.remove('on'); },1600);
568	}
569	
570	function openSheet(which){
571	  const t=T[L], s=document.getElementById('sheet');
572	  const title = which==='terms'?t.sheet_terms_t:t.sheet_nano_t;
573	  const body  = (which==='terms'?t.sheet_terms:t.sheet_nano).map(p=>`<p>${p}</p>`).join('');
574	  s.innerHTML=`<div class="sheet-card"><h3>${title}</h3>${body}<button class="cta ghost" onclick="closeSheet()">${t.sheet_close}</button></div>`;
575	  s.classList.add('on');
576	}
577	function closeSheet(){ document.getElementById('sheet').classList.remove('on'); }
578	
579	function restart(){ i=0; agree=false; howOpen=false; submitting=false; deepLink=''; reg.name=''; reg.phone=''; reg.email=''; reg.gender='m'; repaint(); }
580	function setGender(g){ reg.gender=g; repaint(); }
581	function toggleAgree(){ agree=!agree; repaint(); }
582	function toggleHow(){ howOpen=!howOpen; repaint(); }
583	function setLang(l){ L=l; repaint(); }
584	function toggleLang(){ L=(L==='he'?'en':'he'); repaint(); }
585	
586	init();
587	</script>
588	</body>
589	</html>
